"""TaskWeaver plugin: dominusnode_proxy_url (generated by dominusnode_taskweaver.generate_plugins)."""

from taskweaver.plugin import Plugin, register_plugin

from dominusnode_taskweaver.runtime import run


@register_plugin
class DominusNodeProxyUrl(Plugin):
    def __call__(self, country=None, ip_class=None, session_id=None, allow_http=None, protocol=None) -> str:
        return run(self, "proxy_url", {"country": country, "ip_class": ip_class, "session_id": session_id, "allow_http": allow_http, "protocol": protocol})
